def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for c in text:
        if c.islower():
            original = ord(c) - ord('a')
            new_ord = (original + shift) % 26
            result.append(chr(new_ord + ord('a')))
        elif c.isupper():
            original = ord(c) - ord('A')
            new_ord = (original + shift) % 26
            result.append(chr(new_ord + ord('A')))
        else:
            result.append(c)
    return ''.join(result)

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

